  // src/engine/bazi/day-pillar.ts
  function gregorianToJDN2(year, month, day) {
    const a = Math.floor((14 - month) / 12);
    const y = year + 4800 - a;
    const m = month + 12 * a - 3;
    return day + Math.floor((153 * m + 2) / 5) + 365 * y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) - 32045;
  }
  var EPOCH_YEAR2 = 1900;
  var EPOCH_MONTH2 = 1;
  var EPOCH_DAY2 = 1;
  var EPOCH_STEM_NUMBER = 3;
  var EPOCH_BRANCH_NUMBER = 1;
  function calculateDayPillar(date) {
    const targetJDN = gregorianToJDN2(date.year, date.month, date.day);
    const epochJDN = gregorianToJDN2(EPOCH_YEAR2, EPOCH_MONTH2, EPOCH_DAY2);
    const dayDiff = targetJDN - epochJDN;
    const stemNumber = ((EPOCH_STEM_NUMBER - 1 + dayDiff) % 10 + 10) % 10 + 1;
    const branchNumber = ((EPOCH_BRANCH_NUMBER - 1 + dayDiff) % 12 + 12) % 12 + 1;
    return { stemNumber, branchNumber };
  }
