  // src/engine/shared/parse-birth-date.ts
  function parseBirthDate(birth) {
    const [year, month, day] = birth.birthDate.split("-").map(Number);
    const [hour, minute] = birth.birthTime.split(":").map(Number);
    return new Date(
      year,
      month - 1,
      day,
      hour,
      minute,
      0,
      0
    );
  }

  // src/engine/shared/extract-birth-components.ts
  function extractBirthComponents(date) {
    const startOfYear = new Date(
      date.getFullYear(),
      0,
      0
    );
    const diff = date.getTime() - startOfYear.getTime();
    const oneDay = 1e3 * 60 * 60 * 24;
    return {
      year: date.getFullYear(),
      month: date.getMonth() + 1,
      day: date.getDate(),
      hour: date.getHours(),
      minute: date.getMinutes(),
      weekday: date.getDay(),
      dayOfYear: Math.floor(diff / oneDay)
    };
  }

  // src/engine/shared/to-utc-date.ts
  function toUtcDate(date, timezoneOffsetMinutes = 0) {
    const wallClockAsUtc = Date.UTC(
      date.getFullYear(),
      date.getMonth(),
      date.getDate(),
      date.getHours(),
      date.getMinutes(),
      date.getSeconds(),
      date.getMilliseconds()
    );
    return new Date(
      wallClockAsUtc - timezoneOffsetMinutes * 6e4
    );
  }

  // src/engine/shared/parse-timezone-offset.ts
  function parseTimezoneOffsetMinutes(timezone) {
    if (!timezone) {
      return 0;
    }
    const match = timezone.trim().match(/^([+-])(\d{1,2}):?(\d{2})?$/);
    if (!match) {
      return 0;
    }
    const sign = match[1] === "-" ? -1 : 1;
    const hours = Number(match[2]);
    const minutes = Number(match[3] ?? "0");
    return sign * (hours * 60 + minutes);
  }

  // src/engine/shared/location.ts
  function createLocation(city, state, country, latitude = 0, longitude = 0, timezone = "") {
    return {
      city,
      state,
      country,
      latitude,
      longitude,
      timezone
    };
  }

  // src/engine/astrology/julian-day.ts
  function calculateJulianDay(date) {
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth() + 1;
    const day = date.getUTCDate() + (date.getUTCHours() + date.getUTCMinutes() / 60 + date.getUTCSeconds() / 3600) / 24;
    let y = year;
    let m = month;
    if (m <= 2) {
      y--;
      m += 12;
    }
    const a = Math.floor(y / 100);
    const b = 2 - a + Math.floor(a / 4);
    return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (m + 1)) + day + b - 1524.5;
  }

  // src/engine/astrology/greenwich-sidereal-time.ts
  function calculateGreenwichSiderealTime(julianDay) {
    const t = (julianDay - 2451545) / 36525;
    let gmst = 280.46061837 + 360.98564736629 * (julianDay - 2451545) + 387933e-9 * t * t - t * t * t / 3871e4;
    gmst %= 360;
    if (gmst < 0) {
      gmst += 360;
    }
    return gmst;
  }

  // src/engine/astrology/local-sidereal-time.ts
  function calculateLocalSiderealTime(greenwichSiderealTime, longitude) {
    let lst = greenwichSiderealTime + longitude;
    lst %= 360;
    if (lst < 0) {
      lst += 360;
    }
    return lst;
  }

  // src/engine/astrology/mean-obliquity.ts
  function calculateMeanObliquity(julianCenturies) {
    const seconds = 21.448 - julianCenturies * (46.815 + julianCenturies * (59e-5 - julianCenturies * 1813e-6));
    return 23 + 26 / 60 + seconds / 3600;
  }

