  // src/engine/index.ts
  function calculateNunEngine(birth) {
    const normalizedBirth = normalizeBirthData(birth);
    validateBirthData(normalizedBirth);
    const birthDate = parseBirthDate(normalizedBirth);
    const birthComponents = extractBirthComponents(birthDate);
    const timezoneOffsetMinutes = parseTimezoneOffsetMinutes(normalizedBirth.timezone);
    const utcBirthDate = toUtcDate(birthDate, timezoneOffsetMinutes);
    const location = createLocation(
      normalizedBirth.city,
      normalizedBirth.state,
      normalizedBirth.country,
      normalizedBirth.latitude ?? 0,
      normalizedBirth.longitude ?? 0,
      normalizedBirth.timezone ?? ""
    );
    const julianDay = calculateJulianDay(utcBirthDate);
    const julianCenturies = calculateJulianCenturies(julianDay);
    const greenwichSiderealTime = calculateGreenwichSiderealTime(
      julianDay
    );
    const localSiderealTime = calculateLocalSiderealTime(
      greenwichSiderealTime,
      location.longitude
    );
    const meanObliquity = calculateMeanObliquity(
      julianCenturies
    );
    const eclipticCoordinates = createEclipticCoordinates();
    const equatorialCoordinates = createEquatorialCoordinates();
    const planetaryPositionsRaw = calculatePlanetaryPositions(julianCenturies);
    const { ascendant, midheaven } = calculateAngularPositions(
      localSiderealTime,
      location.latitude,
      meanObliquity
    );
    const planetaryPositions = assignPlanetsToHouses(
      planetaryPositionsRaw,
      ascendant
    );
    const housePositions = calculateHousePositions(ascendant);
    const aspectCollection = calculateAspectCollection(planetaryPositions);
    const context = {
      birth: normalizedBirth,
      localDate: birthDate,
      utcDate: utcBirthDate,
      julianDay,
      julianCenturies,
      greenwichSiderealTime,
      localSiderealTime,
      meanObliquity,
      eclipticCoordinates,
      equatorialCoordinates,
      planetaryPositions,
      ascendant,
      midheaven,
      housePositions,
      aspectCollection,
      components: birthComponents,
      location
    };
    void nunPipeline;
    return {
      astrology: calculateAstrology(context),
      numerology: calculateNumerology(context),
      humanDesign: calculateHumanDesign(context),
      geneKeys: calculateGeneKeys(context),
      tarot: calculateTarot(context),
      runes: calculateRunes(context),
      iching: calculateIChing(context),
      mayaKin: calculateMayaKin(context),
      baZi: calculateBaZi(context),
      kabbalah: calculateKabbalah(context)
    };
  }

