  // src/cross-engine/rules/scoring-rule.ts
  function applyScoringRule(profile, summary) {
    const dimensions = [
      {
        name: "identity",
        values: profile.identity
      },
      {
        name: "personality",
        values: profile.personality
      },
      {
        name: "emotions",
        values: profile.emotions
      },
      {
        name: "mind",
        values: profile.mind
      },
      {
        name: "spirituality",
        values: profile.spirituality
      }
    ];
    dimensions.sort(
      (a, b) => b.values.length - a.values.length
    ).forEach((dimension) => {
      for (const knowledge of dimension.values) {
        if (summary.overview.dominantThemes.some(
          (item) => item.id === knowledge.id
        )) {
          summary.overview.dominantThemes.push(
            knowledge
          );
        }
      }
      summary.recommendations.recommendations.push(
        `${dimension.name}:${dimension.values.length}`
      );
    });
  }

