  function calculateCrossEngine(input, resolver) {
    const profile = createCrossProfile();
    analyzeIdentity(
      input.engine,
      profile,
      resolver
    );
    analyzePersonality(
      input.engine,
      profile,
      resolver
    );
    analyzeEmotions(
      input.engine,
      profile,
      resolver
    );
    analyzeMind(
      input.engine,
      profile,
      resolver
    );
    analyzeSpirituality(
      input.engine,
      profile,
      resolver
    );
    const relationships = createCrossRelationships();
    applyConvergenceRule(
      profile,
      relationships
    );
    const talents = createCrossTalents();
    applyReinforcementRule(
      profile,
      talents
    );
    applySemanticRule(
      profile,
      talents
    );
    const challenges = createCrossChallenges();
    applyContradictionRule(
      profile,
      challenges
    );
    applyComplementarityRule(
      profile,
      relationships
    );
    const purpose = createCrossPurposes();
    const career = createCrossCareers();
    const spirituality = createCrossSpiritualities();
    const summary = createCrossSummary();
    applyScoringRule(
      profile,
      summary
    );
    return {
      profile,
      relationships,
      career,
      spirituality,
      talents,
      challenges,
      purpose,
      summary
    };
  }

